namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, composition, and creative writing." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "World history, cultural studies, and historical analysis." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a PhD in Computer Science from MIT and has 15 years of teaching experience. Her research focuses on programming language design.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is an expert in algorithm optimization with publications in top-tier conferences. Previously worked at Google Research.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 350", Title = "Software Engineering", Description = "Principles of software development including agile methodologies, version control, testing strategies, and system design.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez spent 10 years in industry at Microsoft before joining academia. She specializes in software architecture and team practices.", IsFeatured = false, DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator who has taught calculus for over 20 years. Author of 'Calculus Made Clear'.", IsFeatured = true, DepartmentName = "Mathematics" },
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 230", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and machine learning.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research bridges pure mathematics and machine learning applications. She holds a joint appointment with the CS department.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 3, CourseCode = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop clear, effective writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Torres", InstructorBio = "Prof. Torres is a published author and writing coach who emphasizes practical communication skills for all disciplines.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 7, DepartmentId = 3, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and society.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Angela Brooks", InstructorBio = "Dr. Brooks specializes in 20th-century American fiction and has published extensively on the works of Toni Morrison and James Baldwin.", IsFeatured = true, DepartmentName = "English" },
            new() { Id = 8, DepartmentId = 4, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 3:00–5:00 PM", InstructorName = "Dr. Michael Okafor", InstructorBio = "Dr. Okafor is an experimental physicist whose engaging lecture style has earned him multiple teaching awards.", IsFeatured = false, DepartmentName = "Physics" },
            new() { Id = 9, DepartmentId = 4, CourseCode = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, measurement, and applications to atomic systems.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Dr. Lisa Huang", InstructorBio = "Dr. Huang conducts research in quantum computing and previously worked at IBM Quantum. She makes complex topics accessible.", IsFeatured = false, DepartmentName = "Physics" },
            new() { Id = 10, DepartmentId = 5, CourseCode = "HIST 101", Title = "World Civilizations", Description = "Survey of major world civilizations from ancient Mesopotamia to the modern era, focusing on cultural exchange and conflict.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Thomas Reed", InstructorBio = "Dr. Reed is a historian specializing in cross-cultural encounters. He has conducted field research on four continents.", IsFeatured = false, DepartmentName = "History" },
            new() { Id = 11, DepartmentId = 5, CourseCode = "HIST 220", Title = "Modern European History", Description = "Europe from the French Revolution to the present: industrialization, world wars, decolonization, and European integration.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Catherine Müller", InstructorBio = "Dr. Müller grew up in Berlin and brings firsthand perspective to modern European history. She is a frequent media commentator.", IsFeatured = true, DepartmentName = "History" }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName) &&
               !string.IsNullOrWhiteSpace(request.StudentId) &&
               request.CourseId > 0;
    }
}

