@page "/courses"
@rendermode InteractiveServer
@inject CourseCatalog.Services.CatalogService CatalogService

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses, instructors..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartment">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <p class="text-muted">No courses match your search criteria.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    <tr>
                        <td>@course.CourseCode</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private string searchTerm = string.Empty;
    private int selectedDepartment;
    private List<CourseCatalog.Models.Department> departments = new();
    private List<CourseCatalog.Models.Course> filteredCourses = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        UpdateResults();
    }

    private int _previousDepartment;
    private string _previousSearch = string.Empty;

    protected override void OnParametersSet()
    {
        UpdateResults();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (searchTerm != _previousSearch || selectedDepartment != _previousDepartment)
        {
            _previousSearch = searchTerm;
            _previousDepartment = selectedDepartment;
            UpdateResults();
            StateHasChanged();
        }
    }

    private void UpdateResults()
    {
        int? deptFilter = selectedDepartment > 0 ? selectedDepartment : null;
        filteredCourses = CatalogService.GetCourses(searchTerm, deptFilter);
    }
}

